1025		q, _ := openTempQueue(t)
1026		defer q.Close()
1027		q.RegisterSource("a")
1028		q.Submit(env("m", "a", "b", 1, 100, 0))
1029		q.Advance(1000) // waiting, retry 2000
1030	
1031		// A trusted header arrives before the retry is due: no extra attempt, no
1032		// earlier retry.
1033		if err := q.UpsertHeader(Header{Chain: "a", Height: 100, Root: "0x100", Trusted: true}); err != nil {
1034			t.Fatal(err)
1035		}
1036		r := statusOf(t, q, "m")
1037		if r.Status != StatusWaiting || r.Attempts != 1 || r.NextRetry != 2000 {
1038			t.Fatalf("header update must not process or reschedule: status=%s attempts=%d retry=%d", r.Status, r.Attempts, r.NextRetry)
1039		}
1040		// The waiting message succeeds at its scheduled retry (2000), not earlier.
1041		if _, err := q.Advance(2000); err != nil {
1042			t.Fatal(err)
1043		}
1044		if r := statusOf(t, q, "m"); r.Status != StatusSuccess {
1045			t.Fatalf("want success at scheduled retry, got %s (%s)", r.Status, r.Reason)
1046		}
1047	}
1048	
1049	// A trusted header for an unregistered source chain cannot bypass
1050	// unknown-source.
1051	func TestTrustedHeaderForUnregisteredChainNoBypass(t *testing.T) {
1052		q, _ := openTempQueue(t)
1053		defer q.Close()
1054		// No RegisterSource("ghost").
1055		q.UpsertHeader(Header{Chain: "ghost", Height: 100, Root: "0x100", Trusted: true})
1056		q.Submit(env("m", "ghost", "b", 1, 10, 0))
1057		q.Advance(1000)
1058		if r := statusOf(t, q, "m"); r.Status != StatusUnknownSrc {
1059			t.Fatalf("trusted header must not bypass unknown-source, got %s (%s)", r.Status, r.Reason)
1060		}
1061	}
1062	
1063	// Header updates for one chain do not affect another chain.
1064	func TestHeaderUpdatesPerChainIndependent(t *testing.T) {
1065		q, _ := openTempQueue(t)
1066		defer q.Close()
1067		q.RegisterSource("a")
1068		q.RegisterSource("b")
1069		q.UpsertHeader(Header{Chain: "a", Height: 100, Root: "0xa", Trusted: true})
1070		q.UpsertHeader(Header{Chain: "b", Height: 50, Root: "0xb", Trusted: true})
1071	
1072		q.Submit(env("ma", "a", "c", 1, 100, 0))
1073		q.Submit(env("mb", "b", "c", 2, 100, 0))
1074		q.Advance(1000)
1075		if r := statusOf(t, q, "ma"); r.Status != StatusSuccess {
1076			t.Fatalf("ma should succeed via chain a coverage, got %s", r.Status)
1077		}
1078		if r := statusOf(t, q, "mb"); r.Status != StatusWaiting {
1079			t.Fatalf("mb must wait (chain b coverage 50 < proof 100), got %s", r.Status)
1080		}
1081	}
1082	
1083	// The highest trusted header survives close/reopen and log compaction, so
1084	// coverage is not lost by either.
1085	func TestHighestTrustedSurvivesReopenAndCompaction(t *testing.T) {
1086		dir := t.TempDir()
1087		q, err := Open(dir)
1088		if err != nil {
1089			t.Fatal(err)
1090		}
1091		q.RegisterSource("a")
1092		q.UpsertHeader(Header{Chain: "a", Height: 100, Root: "0x100", Trusted: true})
1093		q.UpsertHeader(Header{Chain: "a", Height: 120, Root: "0x120", Trusted: false})
1094		q.Close()
1095	
1096		q2, err := Open(dir)
1097		if err != nil {
1098			t.Fatal(err)
1099		}
1100		if q2.headers["a"].trusted == nil || q2.headers["a"].trusted.Height != 100 {
1101			t.Fatalf("trusted coverage lost on reopen: %+v", q2.headers["a"].trusted)
1102		}
1103		if q2.headers["a"].latest.Height != 120 || q2.headers["a"].latest.Trusted {
1104			t.Fatalf("latest header should be the untrusted 120: %+v", q2.headers["a"].latest)
1105		}
1106		// Coverage still works after reopen.
1107		q2.Submit(env("m90", "a", "b", 1, 90, 0))
1108		if _, err := q2.Advance(1000); err != nil {
1109			t.Fatal(err)
1110		}
1111		if r := statusOf(t, q2, "m90"); r.Status != StatusSuccess {
1112			t.Fatalf("coverage lost after reopen: %s (%s)", r.Status, r.Reason)
1113		}
1114	
1115		// Compact and reopen again: coverage must survive.
1116		if err := q2.store.compact(q2.snapshot()); err != nil {
1117			t.Fatal(err)
1118		}
1119		q2.Close()
1120		q3, err := Open(dir)
1121		if err != nil {
1122			t.Fatal(err)
1123		}
1124		defer q3.Close()
1125		if q3.headers["a"].trusted == nil || q3.headers["a"].trusted.Height != 100 {
1126			t.Fatalf("trusted coverage lost after compaction: %+v", q3.headers["a"].trusted)
1127		}
1128		if q3.headers["a"].latest.Height != 120 || q3.headers["a"].latest.Trusted {
1129			t.Fatalf("latest header wrong after compaction: %+v", q3.headers["a"].latest)
1130		}
1131		q3.Submit(env("m95", "a", "b", 2, 95, 0))
1132		if _, err := q3.Advance(2000); err != nil {
1133			t.Fatal(err)
1134		}
1135		if r := statusOf(t, q3, "m95"); r.Status != StatusSuccess {
1136			t.Fatalf("coverage lost after compaction: %s (%s)", r.Status, r.Reason)
1137		}
1138	}
1139	
1140	// A terminal message keeps its status and reason after a later header update;
1141	// the nonce is not consumed again.
1142	func TestHeaderUpdateDoesNotReactivateTerminal(t *testing.T) {
1143		q, _ := openTempQueue(t)
1144		defer q.Close()
1145		q.RegisterSource("a")
1146		q.Submit(env("m", "a", "b", 1, 1000, 3000))
1147		q.Advance(1000) // waiting
1148		q.Advance(3000) // expired
1149		if r := statusOf(t, q, "m"); r.Status != StatusExpired {
1150			t.Fatalf("want expired, got %s", r.Status)
1151		}
1152		if err := q.UpsertHeader(Header{Chain: "a", Height: 1000, Root: "0x1000", Trusted: true}); err != nil {
1153			t.Fatal(err)
