1156			t.Fatal(err)
1157		}
1158		if r := statusOf(t, q, "m"); r.Status != StatusExpired {
1159			t.Fatalf("header update reactivated expired message: %s", r.Status)
1160		}
1161		if len(q.consumed) != 0 {
1162			t.Fatalf("nonce consumed by a terminal message: %v", q.consumed)
1163		}
1164	}
1165	
1166	// Historically recorded same-height coverage in an old log is not rejected as
1167	// a conflict; recovery relies only on the header records kept in the log.
1168	func TestHistoricalSameHeightCoverageNotRejected(t *testing.T) {
