206	// assertRecoveredPrefixUsable verifies the acknowledged prefix (source a,
207	// delivered m1) is restored, the dropped final submit for missingID never
208	// existed, and the reopened queue accepts new operations.
209	func assertRecoveredPrefixUsable(t *testing.T, q *Queue, missingID string) {
210		t.Helper()
211		defer q.Close()
212		if !q.sources["a"] {
213			t.Fatal("acknowledged source registration lost")
214		}
215		if r := statusOf(t, q, "m1"); r.Status != StatusSuccess {
216			t.Fatalf("acknowledged success lost: %+v", r)
217		}
218		if winner := q.consumed[newConsumeToken("a", "b", 1)]; winner != "m1" {
219			t.Fatalf("consumed nonce not restored: %q", winner)
220		}
221		if _, ok := q.Query(missingID); ok {
222			t.Fatalf("unacknowledged torn record %q must not exist", missingID)
223		}
224		if q.nextSeq != 1 {
225			t.Fatalf("nextSeq must resume after the last intact submit, got %d", q.nextSeq)
226		}
227		// The recovered queue is fully writable and the new submit gets the seq
228		// that the dropped tail record never acquired.
229		rec, err := q.Submit(env("m3", "a", "b", 3, 10, 0))
230		if err != nil {
231			t.Fatalf("recovered queue must accept new submits: %v", err)
232		}
233		if rec.Seq != 1 {
234			t.Fatalf("new submit should reuse seq 1, got %d", rec.Seq)
235		}
236		if _, err := q.Advance(2000); err != nil {
237			t.Fatal(err)
238		}
239		if r := statusOf(t, q, "m3"); r.Status != StatusSuccess {
240			t.Fatalf("new message should deliver on recovered queue: %+v", r)
241		}
242	}
243	
244	// Corruption strictly after a valid version record (i.e. in the middle) must
245	// still reject the directory and preserve every byte.
246	func TestMidLogCorruptionStillRejectedAndUntouched(t *testing.T) {
247		dir := t.TempDir()
248		q, err := Open(dir)
249		if err != nil {
250			t.Fatal(err)
251		}
252		q.RegisterSource("a")
253		q.Submit(env("m1", "a", "b", 1, 10, 0))
254		q.Submit(env("m2", "a", "b", 2, 10, 0))
255		if err := q.Close(); err != nil {
256			t.Fatal(err)
257		}
258	
259		raw, err := os.ReadFile(filepath.Join(dir, logName))
260		if err != nil {
261			t.Fatal(err)
262		}
263		// The first frame is the version record; flip a byte in the second frame
264		// (the source entry) so its checksum fails before EOF.
265		bad := append([]byte(nil), raw...)
266		pos := len(logMagic)
267		// Skip the whole version frame to land on the record after it.
268		vn := int(binary.BigEndian.Uint32(bad[pos:]))
269		pos += frameHeaderSize + vn + frameCRCsSize
270		bad[pos+frameHeaderSize+1] ^= 0xFF
271	
272		d := t.TempDir()
273		writeRawLog(t, d, bad)
274		assertCorruptAndUntouched(t, d, bad)
275	}
